import{_ as s,o as e,c as a,a2 as d}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"快速部署","description":"灵萌宝塔面板部署指南：从开发者获取安装包，在宝塔安装 MySQL/Redis、上传程序、配置反向代理与 HTTPS，完成首次上线。","frontmatter":{"title":"快速部署","description":"灵萌宝塔面板部署指南：从开发者获取安装包，在宝塔安装 MySQL/Redis、上传程序、配置反向代理与 HTTPS，完成首次上线。"},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1785020677000}'),o={name:"guide/quick-start.md"};function r(i,t,n,l,h,g){return e(),a("div",null,[...t[0]||(t[0]=[d(`<p>本文面向<strong>站点运营方</strong>：您已从开发者或官方渠道拿到 <strong>Linux 安装包</strong>（<code>lingmeng-x.x.x.zip</code>），在 <strong>宝塔面板</strong> 上完成部署。无需安装 Go、无需拉取源码。</p><p>按顺序执行，不要跳步。</p><hr><h2 id="一、部署前准备" tabindex="-1">一、部署前准备 <a class="header-anchor" href="#一、部署前准备" aria-label="Permalink to &quot;一、部署前准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>云服务器</td><td>推荐 <strong>2 核 4G</strong> 及以上，系统 <strong>CentOS 7+ / Ubuntu 20.04+</strong></td></tr><tr><td>宝塔面板</td><td>已安装并可登录（<a href="https://www.bt.cn/" target="_blank" rel="noreferrer">宝塔官网</a> 按系统版本安装）</td></tr><tr><td>安装包</td><td><code>lingmeng-x.x.x.zip</code>（内含可执行文件 <code>lingmeng</code>）</td></tr><tr><td>域名（生产）</td><td>已备案，用于 HTTPS、微信回调</td></tr><tr><td>授权文件</td><td>若开发者提供 <code>license</code> 相关文件，一并保存</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">本文档不是开发者手册</p><p>源码编译、<code>go run</code>、Docker 自建等请向开发者索取技术文档。</p></div><hr><h2 id="二、在宝塔安装运行环境" tabindex="-1">二、在宝塔安装运行环境 <a class="header-anchor" href="#二、在宝塔安装运行环境" aria-label="Permalink to &quot;二、在宝塔安装运行环境&quot;">​</a></h2><p>登录宝塔 → <strong>软件商店</strong>，安装并启动：</p><table tabindex="0"><thead><tr><th>软件</th><th>版本建议</th><th>用途</th></tr></thead><tbody><tr><td><strong>MySQL</strong></td><td>8.0+</td><td>业务数据库</td></tr><tr><td><strong>Redis</strong></td><td>6.0+</td><td>缓存、会话、队列</td></tr><tr><td><strong>Nginx</strong></td><td>任意稳定版</td><td>网站与 HTTPS</td></tr></tbody></table><p>安装完成后，在 <strong>安全</strong> 中放行 <strong><code>80</code>、<code>443</code></strong>；<strong>不要</strong>对公网开放 <code>8080</code>（后端只在本机访问即可）。</p><p><strong>可选（按需）：</strong> Meilisearch、Gorse 等见 <a href="/ops/docker-infra">可选基础设施</a>。</p><hr><h2 id="三、创建-mysql-数据库" tabindex="-1">三、创建 MySQL 数据库 <a class="header-anchor" href="#三、创建-mysql-数据库" aria-label="Permalink to &quot;三、创建 MySQL 数据库&quot;">​</a></h2><p>宝塔 → <strong>数据库</strong> → <strong>添加数据库</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>数据库名</td><td><code>lingmengv2</code></td><td>自定，记住名称</td></tr><tr><td>用户名</td><td><code>lingmeng</code></td><td>与库名可相同</td></tr><tr><td>密码</td><td>强密码</td><td>向导里要填写</td></tr><tr><td>访问权限</td><td>本地服务器</td><td>默认即可</td></tr></tbody></table><p>记下：<strong>数据库名、用户名、密码</strong>。Redis 若设置了密码，也一并记下（宝塔 Redis 设置里查看）。</p><hr><h2 id="四、上传并解压安装包" tabindex="-1">四、上传并解压安装包 <a class="header-anchor" href="#四、上传并解压安装包" aria-label="Permalink to &quot;四、上传并解压安装包&quot;">​</a></h2><ol><li>宝塔 → <strong>文件</strong> → 进入 <strong><code>/www/wwwroot</code></strong></li><li><strong>新建目录</strong> <code>lingmeng</code>（名称可自定，下文以此为例）</li><li>将 <code>lingmeng-x.x.x.zip</code> <strong>上传到</strong> <code>/www/wwwroot/lingmeng</code></li><li>右键 zip → <strong>解压</strong>，得到可执行文件 <strong><code>lingmeng</code></strong></li><li>选中 <code>lingmeng</code> → <strong>权限</strong> → 勾选 <strong>执行</strong>，或终端执行：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /www/wwwroot/lingmeng/lingmeng</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">目录权限</p><p>运行后程序会在同目录生成 <code>config.yaml</code>、<code>logs/</code>、<code>uploads/</code> 等，请保证 <strong><code>www</code> 用户对该目录可写</strong>（宝塔默认站点目录一般已满足）。</p></div><hr><h2 id="五、用进程守护启动后端" tabindex="-1">五、用进程守护启动后端 <a class="header-anchor" href="#五、用进程守护启动后端" aria-label="Permalink to &quot;五、用进程守护启动后端&quot;">​</a></h2><p>宝塔 → <strong>软件商店</strong> → 搜索安装 <strong>「进程守护管理器」</strong>（或 <strong>Supervisor</strong>）。</p><p>添加守护进程：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>名称</td><td><code>lingmeng</code></td></tr><tr><td>启动用户</td><td><code>root</code> 或 <code>www</code>（与目录权限一致即可）</td></tr><tr><td>运行目录</td><td><code>/www/wwwroot/lingmeng</code></td></tr><tr><td>启动命令</td><td><code>/www/wwwroot/lingmeng/lingmeng</code></td></tr><tr><td>进程数量</td><td><code>1</code></td></tr></tbody></table><p>保存并 <strong>启动</strong>。首次启动会在运行目录生成 <strong><code>config.yaml</code></strong>，此时 <code>setup_completed</code> 应为 <code>false</code>。</p><p>在宝塔 <strong>安全</strong> 或服务器防火墙中，确认 <strong>8080 仅本机可访问</strong>（不对公网开放）。</p><hr><h2 id="六、添加网站与反向代理" tabindex="-1">六、添加网站与反向代理 <a class="header-anchor" href="#六、添加网站与反向代理" aria-label="Permalink to &quot;六、添加网站与反向代理&quot;">​</a></h2><h3 id="_6-1-添加站点" tabindex="-1">6.1 添加站点 <a class="header-anchor" href="#_6-1-添加站点" aria-label="Permalink to &quot;6.1 添加站点&quot;">​</a></h3><p>宝塔 → <strong>网站</strong> → <strong>添加站点</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>域名</td><td><code>campus.example.com</code>（你的域名）</td></tr><tr><td>根目录</td><td>可先用默认 <code>/www/wwwroot/campus.example.com</code>（仅占位，API 走反代）</td></tr><tr><td>PHP</td><td><strong>纯静态</strong> 或 <strong>不创建 PHP</strong></td></tr></tbody></table><h3 id="_6-2-配置反向代理" tabindex="-1">6.2 配置反向代理 <a class="header-anchor" href="#_6-2-配置反向代理" aria-label="Permalink to &quot;6.2 配置反向代理&quot;">​</a></h3><p>进入该站点 → <strong>反向代理</strong> → <strong>添加反向代理</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>代理名称</td><td><code>lingmeng-api</code></td></tr><tr><td>目标 URL</td><td><code>http://127.0.0.1:8080</code></td></tr><tr><td>发送域名</td><td><code>$host</code></td></tr></tbody></table><p>在代理配置中 <strong>开启 WebSocket</strong>（消息实时推送依赖 <code>/api/ws</code>）。</p><p>若宝塔版本需手写配置，在 <strong>配置文件</strong> 的 <code>location /</code> 中确保包含：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>WebSocket 路径示例：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /api/ws </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="_6-3-配置-ssl-生产必做" tabindex="-1">6.3 配置 SSL（生产必做） <a class="header-anchor" href="#_6-3-配置-ssl-生产必做" aria-label="Permalink to &quot;6.3 配置 SSL（生产必做）&quot;">​</a></h3><p>站点 → <strong>SSL</strong> → <strong>Let&#39;s Encrypt</strong> 申请证书并 <strong>开启强制 HTTPS</strong>。</p><p>微信/支付宝回调、初始化向导在生产环境 <strong>必须使用 HTTPS</strong>。</p><hr><h2 id="七、初始化向导-必做" tabindex="-1">七、初始化向导（必做） <a class="header-anchor" href="#七、初始化向导-必做" aria-label="Permalink to &quot;七、初始化向导（必做）&quot;">​</a></h2><p>浏览器访问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/setup</span></span></code></pre></div><p>若尚未配置 SSL，可临时用 <code>http://服务器IP:8080/setup</code>（仅测试；<strong>生产请尽快上 HTTPS</strong>）。</p><p>按 <a href="/guide/setup-wizard">初始化向导</a> 逐步填写：</p><ol><li>应用名、端口 <strong><code>8080</code></strong>、<strong>网站地址</strong>（填 <code>https://你的域名</code>，与宝塔站点一致）</li><li>MySQL、Redis 连接信息 → <strong>测试连接</strong></li><li>生成 <strong>登录密钥</strong></li><li><strong>确认安装</strong> → 等待建表 → <strong>重启</strong> 进程守护中的 <code>lingmeng</code></li></ol><hr><h2 id="八、登录管理后台" tabindex="-1">八、登录管理后台 <a class="header-anchor" href="#八、登录管理后台" aria-label="Permalink to &quot;八、登录管理后台&quot;">​</a></h2><ol><li>浏览器打开：<code>https://你的域名/pages_admin/index/index</code></li><li>使用向导创建的管理员登录（常见默认 <code>admin</code> / <code>admin123</code>）</li><li><strong>立即修改密码</strong></li></ol><p>→ <a href="/guide/admin-access">进入管理后台</a></p><hr><h2 id="九、上线后-24-小时内建议配置" tabindex="-1">九、上线后 24 小时内建议配置 <a class="header-anchor" href="#九、上线后-24-小时内建议配置" aria-label="Permalink to &quot;九、上线后 24 小时内建议配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>菜单</th><th>文档</th></tr></thead><tbody><tr><td>1</td><td><strong>系统设置 → 网站信息</strong></td><td><a href="/config/site-info">网站信息</a></td></tr><tr><td>2</td><td><strong>系统设置 → 系统配置 → 文件存储</strong></td><td><a href="/config/system-settings">系统配置</a></td></tr><tr><td>3</td><td><strong>系统设置 → 系统配置 → 微信小程序/公众号</strong></td><td><a href="/features/wechat">微信</a></td></tr><tr><td>4</td><td><strong>区域管理 → 区域列表</strong> 创建校区</td><td><a href="/config/region">区域管理</a></td></tr><tr><td>5</td><td><strong>区域管理 → 用户配置</strong></td><td><a href="/config/user-rules">用户规则</a></td></tr><tr><td>6</td><td><strong>UI管理 → 页面配置</strong></td><td><a href="/features/ui-editor/scenarios/homepage">从零搭建首页</a></td></tr><tr><td>7</td><td><strong>UI管理 → TabBar配置</strong></td><td><a href="/features/ui-editor/tabbar">TabBar</a></td></tr><tr><td>8</td><td>对照</td><td><a href="/ops/checklist">上线检查清单</a></td></tr></tbody></table><hr><h2 id="十、验证部署成功" tabindex="-1">十、验证部署成功 <a class="header-anchor" href="#十、验证部署成功" aria-label="Permalink to &quot;十、验证部署成功&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查</th><th>方法</th></tr></thead><tbody><tr><td>后端进程</td><td>宝塔进程守护中 <code>lingmeng</code> 状态为 <strong>运行中</strong></td></tr><tr><td>API 存活</td><td>访问 <code>https://域名/api/health</code> 或后台 <strong>系统监控 → 系统状态</strong></td></tr><tr><td>管理后台</td><td>能登录、能保存系统配置</td></tr><tr><td>文件上传</td><td>网站信息里上传 Logo 成功</td></tr><tr><td>客户端</td><td>小程序/H5 能打开首页（需单独发布客户端并配置合法域名）</td></tr></tbody></table><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>进程启动后立即退出</strong></p><ul><li>检查 <code>lingmeng</code> 是否有执行权限</li><li>查看 <code>/www/wwwroot/lingmeng/logs/</code> 下日志</li><li>8080 端口是否被占用（宝塔 <strong>安全</strong> 或 <code>netstat</code> 排查）</li></ul><p><strong>反向代理 502</strong></p><ul><li>进程守护是否运行中</li><li>反代目标是否为 <code>127.0.0.1:8080</code></li><li>修改配置后 <strong>重载 Nginx</strong></li></ul><p><strong>无法访问 <code>/setup</code></strong></p><ul><li>是否已完成安装（<code>config.yaml</code> 里 <code>setup_completed: true</code> 后不可重复安装）</li><li>是否用了正确的域名与 HTTPS</li></ul><p><strong>更新版本</strong></p><ul><li>在进程守护中 <strong>停止</strong> 服务 → 备份 <code>config.yaml</code> 与数据库 → 上传新版本 zip 覆盖 <code>lingmeng</code> 二进制 → <strong>启动</strong> 服务（具体以开发者说明为准）</li></ul><hr><h2 id="默认账号说明" tabindex="-1">默认账号说明 <a class="header-anchor" href="#默认账号说明" aria-label="Permalink to &quot;默认账号说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>用户名</td><td><code>admin</code></td><td>向导可修改</td></tr><tr><td>密码</td><td><code>admin123</code></td><td><strong>必须改</strong></td></tr></tbody></table><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/setup-wizard">初始化向导详解</a></li><li><a href="/guide/modules">功能模块总览</a></li><li><a href="/config/system-settings">系统配置总览</a></li><li><a href="/ops/checklist">上线检查清单</a></li></ul>`,78)])])}const k=s(o,[["render",r]]);export{c as __pageData,k as default};
